import React from 'react';
import { Container, Row, Col, Table, Badge, Button } from 'reactstrap';
import useFetch from '../../hooks/useFetch';
import { BASE_URL } from '../../utils/config';

const ManageUsers = () => {
   const { data: users, loading, error } = useFetch(`${BASE_URL}/users`);

   return (
      <section className="mt-5 pt-5">
         <Container>
            <Row>
               <Col lg='12'>
                  <div className="d-flex align-items-center justify-content-between mb-4">
                     <h3 className="fw-bold">Quản lý người dùng</h3>
                     <Badge color="primary" className="p-2">
                        Tổng cộng: {users?.length || 0}
                     </Badge>
                  </div>
                  
                  {loading && <h4 className="text-center pt-5">Đang tải dữ liệu...</h4>}
                  {error && <div className="alert alert-danger text-center">{error}</div>}

                  {!loading && !error && (
                     <Table hover responsive className="shadow-sm bg-white rounded overflow-hidden">
                        <thead className="bg-light">
                           <tr>
                              <th>Tên người dùng</th>
                              <th>Email</th>
                              <th>Quyền hạn</th>
                              <th className="text-center">Thao tác</th>
                           </tr>
                        </thead>
                        <tbody>
                           {users?.map(user => (
                              <tr key={user._id}>
                                 <td className="align-middle">{user.username}</td>
                                 <td className="align-middle">{user.email}</td>
                                 <td className="align-middle">
                                    <Badge color={user.role === 'admin' ? "danger" : "success"}>
                                       {user.role}
                                    </Badge>
                                 </td>
                                 <td className="text-center">
                                    <Button color="outline-danger" size="sm" title="Xóa người dùng">
                                       Xóa
                                    </Button>
                                 </td>
                              </tr>
                           ))}
                        </tbody>
                     </Table>
                  )}
               </Col>
            </Row>
         </Container>
      </section>
   );
};

export default ManageUsers;
